        return;
    const auto agent_before = agent_settings();
    // One JusPrin window over the app at a time.
    m_preferences_open = true;
    {
        V1Import::WelcomeBackWindow window(m_frame, *m_theme, *m_workspace, *report);
        window.ShowModal();
