def with_free_plan(queryset):
    return queryset.filter(Q(subscription__isnull=True) | Q(subscription__expired_at__lt=timezone.now()))


def start_free_trial(sender, instance, created, **kwargs):
    if created:
        user_id = instance.id
        (sub, _) = Subscription.objects.get_or_create(
            user_id=user_id,
            defaults={'external_id': '', 'external_user_id': '', 'printers_subscribed': 3, 'plan_id': 'pro-trial', 'unlimited_dh': False, 'expired_at': timezone.now() +
                      timedelta(days=30)},
